import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import path from 'node:path';

export const LIMITS = { title: 200, author: 200, notes: 10000 };

// Trims and checks user input. Returns { value } on success or { errors } otherwise.
export function validateBook(input) {
  const value = {
    title: String(input.title ?? '').trim(),
    author: String(input.author ?? '').trim(),
    notes: String(input.notes ?? '').trim(),
  };
  const errors = {};
  if (!value.title) errors.title = 'Title is required.';
  for (const [field, max] of Object.entries(LIMITS)) {
    if (value[field].length > max) errors[field] = `Keep this under ${max} characters.`;
  }
  return Object.keys(errors).length ? { errors, value } : { value };
}

async function load(filePath) {
  let text;
  try {
    text = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // A broken file is never silently replaced: starting with an empty list would
  // overwrite the reader's books on the next save.
  let data;
  try {
    data = JSON.parse(text);
  } catch (err) {
    throw new Error(`Could not parse ${filePath}: ${err.message}. Fix or move the file and restart.`);
  }
  if (!Array.isArray(data)) throw new Error(`${filePath} should contain a JSON array of books.`);
  return data;
}

export async function openStore(filePath) {
  let books = await load(filePath);
  let queue = Promise.resolve();

  async function write(next) {
    await mkdir(path.dirname(filePath), { recursive: true });
    // Write to a temp file and rename so a crash mid-write can't leave a half-written file.
    const tmp = `${filePath}.${process.pid}.tmp`;
    await writeFile(tmp, JSON.stringify(next, null, 2) + '\n');
    await rename(tmp, filePath);
  }

  // Runs changes one at a time so concurrent requests can't clobber each other's
  // writes. Memory is only updated once the file has been saved.
  function update(change) {
    const run = queue.then(async () => {
      const next = books.map((book) => ({ ...book }));
      const result = change(next);
      await write(next);
      books = next;
      return result;
    });
    queue = run.catch(() => {});
    return run;
  }

  function newId() {
    let id;
    do id = randomBytes(6).toString('base64url');
    while (books.some((book) => book.id === id));
    return id;
  }

  return {
    list() {
      return books.map((book) => ({ ...book }));
    },

    get(id) {
      const book = books.find((b) => b.id === id);
      return book ? { ...book } : undefined;
    },

    // Expects input that has already passed validateBook.
    add({ title, author, notes }) {
      return update((next) => {
        const book = { id: newId(), title, author, notes, addedAt: new Date().toISOString(), finishedAt: null };
        next.push(book);
        return { ...book };
      });
    },

    // Resolves to the updated book, or undefined if there is no book with that id.
    markFinished(id) {
      return update((next) => {
        const book = next.find((b) => b.id === id);
        if (!book) return undefined;
        book.finishedAt ??= new Date().toISOString();
        return { ...book };
      });
    },
  };
}

