import { LIMITS } from './store.js';

const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, (ch) => ESCAPES[ch]);
}

function formatDate(iso) {
  return iso ? iso.slice(0, 10) : '';
}

const STYLES = `
  body { font-family: system-ui, sans-serif; max-width: 42rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  .empty { color: #666; font-style: italic; }
  form.add { display: grid; gap: .75rem; padding: 1rem; background: #f6f6f6; border-radius: 6px; }
  form.add label { display: grid; gap: .25rem; font-weight: 600; }
  input, textarea { font: inherit; padding: .4rem; border: 1px solid #bbb; border-radius: 4px; font-weight: normal; }
  button { font: inherit; padding: .3rem .8rem; cursor: pointer; }
  form.inline { margin: 0; }
  .error { color: #b00020; font-weight: normal; font-size: .9rem; }
  .notes { white-space: pre-wrap; background: #fafafa; border-left: 3px solid #ddd; padding: .5rem 1rem; }
  .actions { display: flex; gap: .5rem; align-items: center; }
`;

function layout({ title, body, nonce }) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>${STYLES}</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
<script nonce="${nonce}">
  // "Copy link" button on the book page. Falls back to a prompt where the
  // clipboard API isn't available (e.g. plain http on a non-localhost address).
  for (const button of document.querySelectorAll('[data-copy-link]')) {
    button.hidden = false;
    button.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(location.href);
        button.textContent = 'Link copied';
      } catch {
        prompt('Copy this link:', location.href);
      }
    });
  }
</script>
</body>
</html>`;
}

function finishButton(book, returnTo) {
  return `<form class="inline" method="post" action="/books/${encodeURIComponent(book.id)}/finish">
    <input type="hidden" name="return" value="${returnTo}">
    <button type="submit">Mark as finished</button>
  </form>`;
}

function bookList(books, { emptyText, showFinish }) {
  if (!books.length) return `<p class="empty">${escapeHtml(emptyText)}</p>`;
  const items = books.map((book) => {
    const byline = book.author ? ` <span class="muted">by ${escapeHtml(book.author)}</span>` : '';
    const meta = book.finishedAt ? `<span class="muted">${formatDate(book.finishedAt)}</span>` : '';
    return `<li>
      <span><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a>${byline}</span>
      ${showFinish ? finishButton(book, 'home') : meta}
    </li>`;
  });
  return `<ul class="books">${items.join('')}</ul>`;
}

function field(name, label, { values, errors, multiline = false, required = false }) {
  const value = escapeHtml(values[name]);
  const attrs = `name="${name}" maxlength="${LIMITS[name]}"${required ? ' required' : ''}`;
  const control = multiline ? `<textarea ${attrs} rows="4">${value}</textarea>` : `<input ${attrs} value="${value}">`;
  const error = errors[name] ? `<span class="error">${escapeHtml(errors[name])}</span>` : '';
  return `<label>${label}${control}${error}</label>`;
}

export function homePage({ books, values = {}, errors = {}, nonce }) {
  const reading = books
    .filter((b) => !b.finishedAt)
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.finishedAt)
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const body = `
<h2>Currently reading</h2>
${bookList(reading, { emptyText: 'Nothing on the go. Add a book below.', showFinish: true })}

<h2>Finished</h2>
${bookList(finished, { emptyText: 'No finished books yet.', showFinish: false })}

<h2>Add a book</h2>
<form class="add" method="post" action="/books">
  ${field('title', 'Title', { values, errors, required: true })}
  ${field('author', 'Author', { values, errors })}
  ${field('notes', 'Notes', { values, errors, multiline: true })}
  <div><button type="submit">Add book</button></div>
</form>`;
  return layout({ title: 'My books', body, nonce });
}

export function bookPage({ book, nonce }) {
  const status = book.finishedAt
    ? `Finished on ${formatDate(book.finishedAt)}`
    : `Reading since ${formatDate(book.addedAt)}`;
  const notes = book.notes
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : '<p class="empty">No notes.</p>';

  const body = `
<article>
  <h2>${escapeHtml(book.title)}</h2>
  <p>${book.author ? `by ${escapeHtml(book.author)}` : '<span class="muted">Unknown author</span>'}</p>
  <p class="muted">${status}</p>
  <h3>Notes</h3>
  ${notes}
  <p class="actions">
    ${book.finishedAt ? '' : finishButton(book, 'book')}
    <button type="button" data-copy-link hidden>Copy link</button>
  </p>
</article>
<p><a href="/">&larr; All books</a></p>`;
  return layout({ title: book.title, body, nonce });
}

export function notFoundPage({ nonce }) {
  const body = `<h2>Book not found</h2><p>That link doesn't match any book. <a href="/">See all books</a>.</p>`;
  return layout({ title: 'Not found', body, nonce });
}

export function errorPage({ message, nonce }) {
  const body = `<h2>Something went wrong</h2><p>${escapeHtml(message)}</p><p><a href="/">Back to books</a></p>`;
  return layout({ title: 'Error', body, nonce });
}

