import { randomBytes } from 'node:crypto';
import { validateBook } from './store.js';
import { bookPage, errorPage, homePage, notFoundPage } from './views.js';

const MAX_BODY_BYTES = 64 * 1024;

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

async function readForm(req) {
  const type = req.headers['content-type'] ?? '';
  if (!type.startsWith('application/x-www-form-urlencoded')) {
    throw new HttpError(415, 'Expected a form submission.');
  }
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'That submission is too large.');
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString('utf8')));
}

// No accounts, so at least stop other websites from submitting forms to this one.
function isCrossSite(req) {
  if (req.headers['sec-fetch-site'] === 'cross-site') return true;
  const origin = req.headers.origin;
  if (!origin || origin === 'null') return false;
  try {
    return new URL(origin).host !== req.headers.host;
  } catch {
    return true;
  }
}

function sendHtml(res, status, render) {
  const nonce = randomBytes(16).toString('base64');
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Security-Policy': `default-src 'none'; style-src 'unsafe-inline'; script-src 'nonce-${nonce}'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'`,
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'same-origin',
  });
  res.end(render(nonce));
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createHandler(store) {
  async function route(req, res) {
    const { pathname } = new URL(req.url, 'http://localhost');
    const method = req.method;

    if (method === 'POST' && isCrossSite(req)) throw new HttpError(403, 'Cross-site form submissions are not allowed.');

    if (pathname === '/') {
      if (method !== 'GET' && method !== 'HEAD') throw new HttpError(405, 'Method not allowed.');
      return sendHtml(res, 200, (nonce) => homePage({ books: store.list(), nonce }));
    }

    if (pathname === '/books') {
      if (method !== 'POST') throw new HttpError(405, 'Method not allowed.');
      const { value, errors } = validateBook(await readForm(req));
      if (errors) {
        return sendHtml(res, 400, (nonce) => homePage({ books: store.list(), values: value, errors, nonce }));
      }
      await store.add(value);
      return redirect(res, '/');
    }

    const bookMatch = pathname.match(/^\/books\/([A-Za-z0-9_-]+)$/);
    if (bookMatch) {
      if (method !== 'GET' && method !== 'HEAD') throw new HttpError(405, 'Method not allowed.');
      const book = store.get(bookMatch[1]);
      if (!book) return sendHtml(res, 404, (nonce) => notFoundPage({ nonce }));
      return sendHtml(res, 200, (nonce) => bookPage({ book, nonce }));
    }

    const finishMatch = pathname.match(/^\/books\/([A-Za-z0-9_-]+)\/finish$/);
    if (finishMatch) {
      if (method !== 'POST') throw new HttpError(405, 'Method not allowed.');
      const form = await readForm(req);
      const book = await store.markFinished(finishMatch[1]);
      if (!book) return sendHtml(res, 404, (nonce) => notFoundPage({ nonce }));
      return redirect(res, form.return === 'book' ? `/books/${encodeURIComponent(book.id)}` : '/');
    }

    return sendHtml(res, 404, (nonce) => notFoundPage({ nonce }));
  }

  return async function handler(req, res) {
    try {
      await route(req, res);
    } catch (err) {
      const status = err instanceof HttpError ? err.status : 500;
      if (status === 500) console.error(err);
      const message = status === 500 ? 'The server hit an error. Your change may not have been saved.' : err.message;
      if (res.headersSent) return res.end();
      sendHtml(res, status, (nonce) => errorPage({ message, nonce }));
    }
  };
}

