import http from 'node:http';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createHandler } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir, dataFile, server, base;

async function start() {
  const store = await openStore(dataFile);
  server = http.createServer(createHandler(store));
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((resolve) => server.close(resolve));
}

function post(pathname, fields, headers = {}) {
  return fetch(base + pathname, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
    headers,
  });
}

async function addBook(fields) {
  const res = await post('/books', fields);
  expect(res.status).toBe(303);
  const books = JSON.parse(await readFile(dataFile, 'utf8'));
  return books.find((b) => b.title === fields.title);
}

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), 'books-'));
  dataFile = path.join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe('books app', () => {
  it('shows empty lists and the add form on first open', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
    expect(html).toContain('<form class="add" method="post" action="/books">');
  });

  it('adds a book, lists it as currently reading and shows its page', async () => {
    const book = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'Spice.\nSandworms.' });

    const home = await (await fetch(base + '/')).text();
    const [reading, finished] = home.split('<h2>Finished</h2>');
    expect(reading).toContain(`href="/books/${book.id}">Dune</a>`);
    expect(finished).not.toContain('Dune');

    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const page = await res.text();
    expect(page).toContain('<h2>Dune</h2>');
    expect(page).toContain('by Frank Herbert');
    expect(page).toContain('Spice.\nSandworms.');
  });

  it('marks a book as finished and moves it to the finished list', async () => {
    const book = await addBook({ title: 'Emma', author: 'Jane Austen' });

    const res = await post(`/books/${book.id}/finish`, { return: 'home' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const home = await (await fetch(base + '/')).text();
    const [reading, finished] = home.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Emma');
    expect(finished).toContain('Emma');

    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(page).toContain('Finished on');
    expect(page).not.toContain('Mark as finished');
  });

  it('redirects back to the book page when finishing from there', async () => {
    const book = await addBook({ title: 'Ulysses' });
    const res = await post(`/books/${book.id}/finish`, { return: 'book' });
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);
  });

  it('keeps books after a restart', async () => {
    const book = await addBook({ title: 'Middlemarch', author: 'George Eliot', notes: 'Long.' });
    await post(`/books/${book.id}/finish`, {});
    await stop();
    await start();

    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(page).toContain('<h2>Middlemarch</h2>');
    expect(page).toContain('Long.');
    expect(page).toContain('Finished on');
  });

  it('requires a title and keeps what was typed', async () => {
    const res = await post('/books', { title: '   ', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('value="Someone"');
    expect(html).toContain('>kept</textarea>');
  });

  it('escapes user content', async () => {
    const book = await addBook({ title: '<script>alert(1)</script>', author: '"><img src=x>', notes: '<b>hi</b>' });
    const page = await (await fetch(`${base}/books/${book.id}`)).text();
    expect(page).not.toContain('<script>alert(1)</script>');
    expect(page).not.toContain('<img src=x>');
    expect(page).toContain('&lt;script&gt;alert(1)&lt;/script&gt;');
    expect(page).toContain('&lt;b&gt;hi&lt;/b&gt;');
  });

  it('returns 404 for unknown books', async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
  });

  it('rejects cross-site form posts', async () => {
    const res = await post('/books', { title: 'Spam' }, { Origin: 'https://evil.example' });
    expect(res.status).toBe(403);
    const home = await (await fetch(base + '/')).text();
    expect(home).not.toContain('Spam');
  });

  it('does not lose books when several are added at once', async () => {
    const titles = Array.from({ length: 20 }, (_, i) => `Book ${i}`);
    await Promise.all(titles.map((title) => post('/books', { title })));
    const saved = JSON.parse(await readFile(dataFile, 'utf8'));
    expect(saved.map((b) => b.title).sort()).toEqual([...titles].sort());
  });
});

describe('openStore', () => {
  it('refuses to start from a corrupt data file instead of overwriting it', async () => {
    const file = path.join(dir, 'broken.json');
    await writeFile(file, '{ not json');
    await expect(openStore(file)).rejects.toThrow(/Could not parse/);
    expect(await readFile(file, 'utf8')).toBe('{ not json');
  });
});

